import csv,json,zipfile
from pathlib import Path
from build_btc_web_report import read,table
from btc_perp_bot.research.archive import canonical,sha
ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-sentiment-20261003'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');unc=read(RUN/'uncertainty.json');diag=read(RUN/'diagnostics.json');activity=read(RUN/'activity.json');identity=read(RUN/'control-identity.json');fc=read(RUN/'forecast-summary.json')
 assert len(s)==v['accounts']==72 and rep['all_bytes_equal'] and rep['matched_files']==121 and not sel['passed']
 rows=[];base=[];annual=[];cost=[];ci=[];forecast=[]
 for n in ('FG_INFO','FG_MKT','FG_SENT','FG_PRICE','FG_INV','FG_TREND'):
  a=s['main-'+n+'-base']['metrics'];b=s['recent-'+n+'-base']['metrics'];base.append([n+(' · 기본' if n=='FG_INFO' else ' · 대조'),f"{a['return_pct']:+.2f}",f"{a['max_drawdown_pct']:.2f}",f"{b['return_pct']:+.2f}",f"{b['max_drawdown_pct']:.2f}",str(a['round_trips'])+' / '+str(b['round_trips'])])
  for p in ('main','recent'):
   key=p+'-'+n+'-base';e=s[key];m=e['metrics'];d=diag[key+'.json.gz']['sides'];annual.append([n,p,*[f"{e['annual'][y]['return_pct']:+.2f}" if y in e['annual'] else '해당 없음' for y in ('2022','2023','2024','2025','2026')]])
   cost.append([n,p,f"{m['gross_pnl']:+.2f}",f"{m['fees']+m['impact']:.2f}",f"{m['funding']:+.4f}",f"{m['mean_exposure']*100:.2f}",f"{m['realized_vol_pct']:.2f}",f"{d['BS']['net']:+.2f}",f"{d['BP']['net']:+.2f}"])
   for c in ('FG_MKT','FG_SENT','FG_PRICE','FG_TREND'):
    q=unc[p+'-'+n]['vs_'+c][1]['ci95'];ci.append([n,p,c,f'{q[0]:+.5f} ~ {q[1]:+.5f}'])
 for key,e in s.items():
  p,n,c=key.split('-');m=e['metrics'];rows.append({'strategy':n,'period':p,'scenario':c,**{k:m[k] for k in ('return_pct','max_drawdown_pct','realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure')}})
 for p,lags in fc.items():
  for lag,models in lags.items():
   for n,x in models.items():forecast.append([p,lag,n,x['n'],f"{x['mse']:.9f}",f"{x['sign_accuracy']*100:.2f}",x['constraint_weeks']])
 evidence={'build':'1003s1','account_rows':rows,'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'diagnostics':diag,'activity':activity,'control_identity':identity,'forecast_summary':fc,'scope':'BTC-only development; Alternative.me composite FGI beyond selected market controls, not pure sentiment or causal evidence. Current historical vintage and D+2 assumed availability, not verified first releases or unused OOS. No accepted strategy','provider_attribution':{'name':'Alternative.me','definition_url':'https://alternative.me/crypto/fear-and-greed-index/','api_url':'https://api.alternative.me/fng/?limit=0&format=json','retrieved_utc':'2026-10-03T09:02:43Z','transformation':'daily normalization; g=(mean of seven daily index values-50)/50; not provider endorsement'}}
 (DOWN/'btc-sentiment-evidence.json').write_bytes(canonical(evidence))
 with (DOWN/'btc-sentiment-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
 with zipfile.ZipFile(DOWN/'btc-sentiment-evidence.zip','w',compression=zipfile.ZIP_STORED) as z:
  files=[(p,'run/'+p.name) for p in sorted(RUN.iterdir()) if p.is_file()]
  for n in ('btc_sentiment_study.py','test_btc_sentiment_study.py','verify_btc_sentiment_study.py','reproduce_btc_sentiment_study.py','audit_btc_sentiment_data.py','collect_btc_sentiment_data.py','btc_target_ledger.py'):files.append((ROOT/'tools'/n,'source/'+n))
  folder=ROOT/'data/btc-sentiment-20261003'
  for p in sorted(folder.rglob('*')):
   if p.is_file():files.append((p,'input/'+str(p.relative_to(folder))))
  for n in ('daily.json','independent-audit.json','prepare-audit.json'):files.append((ROOT/'data/btc-cashflow-20261003'/n,'input/reused-spot/'+n))
  files.extend([(ROOT/'data/btc-venue-20261003/masks.json','input/btc-no-trade-mask.json'),(DOC/'EXPERIMENT_BTC_SENTIMENT_20261003.md','source/EXPERIMENT_BTC_SENTIMENT_20261003.md')])
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,3,0,0,0)),p.read_bytes())
  z.writestr(zipfile.ZipInfo('DATA-SOURCES.txt',(2026,10,3,0,0,0)),"""Fear & Greed Index source: Alternative.me, https://alternative.me/crypto/fear-and-greed-index/ ; API https://api.alternative.me/fng/?limit=0&format=json ; retrieved 2026-10-03T09:02:43Z. Provider attribution applies to index values, not to our trading results. Original history/latest10 responses are unchanged. Daily normalization, missing masks, g=(7-day mean-50)/50 and forecasts are our transformations, not provider-endorsed. Historical first publication times and methodology vintages are not established. D+2 and additional 7-day delay are assumptions, not point-in-time proof. Current full raw response includes September/October 2026 for provenance only; calculations stop 2026-08-31.
Included: all 72 accounts, weekly inputs/forecasts, independent accounting verification and replay hashes, public BTC aggregate sentiment responses, provider definition and fetch metadata, reused daily BTCUSDT spot quote-volume data and previous quality receipts, new source/test/audit tools, and no-trade mask. Raw BTC market ZIPs/checksums, normalized common market, repository paths and common Python dependencies remain separate. This is not a standalone full environment. No paper PDFs, individual social records, addresses, wallets, secrets or live trading data. Binance market aggregates are a separate source, not attributed to Alternative.me.
""")
 html='<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src \'self\';script-src \'none\';style-src \'self\';img-src \'self\' data:;connect-src \'none\';object-src \'none\';base-uri \'none\';form-action \'none\'"><title>BTC 감정 합성지표 정보 검증</title><link rel="icon" href="assets/icon.svg"><link rel="stylesheet" href="assets/btc-continuation.css"></head><body><a class="skip" href="#results">결과로 이동</a><header><a href="./">BTC RESEARCH</a><nav><a href="btc-web-research.html">전체 연구 기록</a><a href="#downloads">검증 자료</a></nav></header><main><p class="eyebrow">BTC-ONLY · BUILD1003s1</p><h1>감정지표를 더해도<br>최근 손실과 위험 기준을 넘지 못했습니다.</h1><p class="lead">가격·변동성·낙폭·거래대금에 합성 감정지표가 정보를 더하는지 검정했습니다. 주기간 수익 증가는 있었지만 최근 손실, 높은 낙폭과 변동성, 악화된 예측오차로 기본 후보를 기각했습니다.</p><div class="facts"><article><b>72</b><span>조건별 가상계좌</span></article><article><b>기각</b><span>FG_INFO 기본 후보</span></article><article><b>121</b><span>파일 소켓차단 바이트 일치</span></article></div><p class="boundary">2022–2025와 2026.01–08은 이미 본 개발 자료입니다. 현재 역사 응답은 당시 첫 공표값·공표시각을 증명하지 않습니다. 새 OOS·순수 심리 측정·실전 결과가 아닙니다.</p><p>Fear &amp; Greed Index 자료 출처: <a href="https://alternative.me/crypto/fear-and-greed-index/">Alternative.me</a>. 지표 정규화·모형·매매 결과는 자체 변환이며 공급자의 승인이나 보증이 아닙니다.</p><section id="results"><h2>기본과 모든 대조군</h2><p>각1,000USDT. 수익과 최대낙폭(DD)은 %. TREND는 기존 E_SPOT와 일별·주요회계가 같습니다.</p>'+table(['규칙','4년 수익','4년 DD','최근 수익','최근 DD','주/최근 보유구간'],base,'base-results')+'<p>기본 주 +70.62%·DD14.70%·연변동성14.67%·Sharpe0.983, 최근 −3.90%·DD14.49%. 주 수익52.838713%·DD13.561952%·변동성13.343621%·Sharpe0.8과 최근 수익4.628391%·DD10.450946%의 기존 기준을 유지했습니다. 2022년도 −4.21%였습니다.</p><p>시장 모형보다 계좌 수익은 높았지만, 추세 대조의 최근 +0.89%보다 낮고 기본의 예측오차는 두 기간 모두 악화했습니다. 반대 대조의 최근 +2.63%를 보고 기본으로 바꾸지 않았습니다. 창·위험목표·기각 기준도 바꾸지 않았습니다.</p></section><section><h2>순수 감정이 아닌 합성지표</h2><p>Alternative.me 설명상 변동성·낙폭25%, 모멘텀·거래량25%, 소셜15%, 설문15%(중단), BTC 점유율10%, 검색추세10%의 혼합입니다. 정확한 결합식·중단 비중 재배분·과거 방법 변경일은 공개되지 않았습니다. 이미 가격 정보가 포함돼 감정의 독립 인과효과라고 볼 수 없습니다.</p><p>30/90일 가격 변화·수익 표준편차 로그·각 창의 최대 peak-to-trough 낙폭과 30/90일 평균 USDT 거래대금 비율의 로그, 총7개 시장 통제를 사용했습니다. 여기에 g=(최근7일 지표평균−50)/50을 더했습니다. 50은 단위 변환 기준이지 매매 문턱이 아닙니다. 이 통제도 비공개 공식의 모든 가격 성분을 제거한다고 보장하지 않습니다.</p><p>Bourghelle 등2022 원문은 주로 전체표본의 변동성·감정 체제 연관성을 추정했고, 미래 예측력 검증을 후속 연구로 남겼습니다. 이번 다음7일 수익 모형은 자체 단순화이며 논문 복제나 원문에 없는 순수익 성과가 아닙니다. 개인 소셜 기록·다른 자산 시세는 수집하지 않았습니다.</p></section><section><h2>현재 자료와 실제 가용 시계를 구별했습니다</h2><p>2026-10-03 09:02:43UTC 공식 API 응답3,163일을 동결했습니다. 연구범위2,435일 중2024-10-26은 누락이라 채우지 않았고, 별도 최신10일 응답은 값·날짜·분류가 같았습니다. 원문 응답의2026.09–10은 출처 보존용일 뿐 피처·목표·성과에서 제외했습니다.</p><p>현재 역사 timestamp는 모두00UTC지만 공식문서의2019년 예제는05UTC입니다. 현재 갱신 카운트다운이 다음00UTC를 가리키는 것만으로 과거 최초 공표시점을 알 수 없습니다. 월요일 T의 최신 입력일을 T−2일로 두고 추가7일 자료지연도 검사했으나, 이 여유가 빈티지 문제를 해결하지는 않습니다.</p><p>91개 연속 일별종가·90일 거래대금은 기존 오류일 마스크를 그대로 적용했습니다. 한 날이라도 무효이면 모든 모형에서 같은 행을 제외합니다. 기본 주기간184일은 피처 무효,534일은 모형 준비 미달이며 임의 보간이나 학습 최소치 완화는 없었습니다. 가격 모멘텀 방향으로 돌아가는 날도 모두 회계에 포함했습니다.</p></section><section><h2>추가 예측력과 비용 이후 계좌</h2><p>월요일마다104달력주 안에서 최소52개 공통유효주를 학습합니다. 목표가 완료된 주만 사용하고 최근1주를 분리하며, 달력1주 HAC와 한 표준오차·거래비용 문턱을 적용합니다. INFO=시장7+g, MKT=시장7, SENT=가격30/90+g, PRICE=가격30/90. 계수 부호는 제한하지 않습니다.</p><p>INFO의 예측과 MKT 대비 추가분 방향이 같을 때만 기존 추세를 바꿉니다. 반대 대조는 같은 발동 주를 사용합니다. 기본 주30주206일·최근17주110일 발동이며 부분 주도 포함합니다. 방향은 주간 고정, 위험량만 매일 갱신합니다.</p><p>공통 예측은 주132개·최근34개. 주 MSE INFO0.004423910, MKT0.004365841, PRICE0.004167705; 최근 INFO0.005273417, MKT0.004711542, PRICE0.004363628. 양기간 모두 시장·가격 대조보다 오차가 큽니다.</p><p>비용2배 +63.05% / −4.67%, 추가1h 실행 +68.24% / −4.51%, 추가24h +44.29% / −9.01%, 자료7일 추가지연 +57.22% / −10.83%. 위험10%도 +32.48% / −2.03%이며 구제책으로 승격하지 않았습니다.</p>'+ '<details><summary>예측과 자료지연</summary>' + table(['기간','추가지연(일)','모형','공통주','MSE','방향정확도%','부호제약주'],forecast,'forecast-results') + '</details><details><summary>연도별 수익</summary>' + table(['규칙','기간','2022','2023','2024','2025','2026'],annual,'annual-results') + '</details><details><summary>롱숏·비용·펀딩·위험</summary>' + table(['규칙','기간','가격손익','비용','펀딩','평균노출%','연변동성%','롱 순손익','숏 순손익'],cost,'cost-results') + '</details><details><summary>모든 대조군 차이의 불확실성</summary><p>14일 원형블록2,000회95%구간(%/일);7/28일은 JSON. 반복개발·자료 빈티지 문제를 해소하는 독립 입증이 아닙니다.</p>' + table(['규칙','기간','대조','일수익차95%구간'],ci,'uncertainty-results') + '</details></section>'
 html+='<section><h2>모든 비용·지연·위험 조건</h2><p>현물10bp/선물5bp 수수료+각1.5bp 불리한 impact, 실제 funding, 수량·금액 최소치·5%p 조절밴드·종료비용 포함. 위험목표20%/진입 명목상한1배, 비용2배·추가1/24h 실행·위험10%·추가7일 자료지연을 보존했습니다. 실제호가·부분체결·과거규정·순간청산·세금·운영비는 완전히 복원하지 못했습니다.</p><details id="matrix"><summary>72계좌 전체 보기</summary>'+table(['규칙','기간','조건','수익%','DD%','연변동성%','보유구간','비용'],[[r['strategy'],r['period'],r['scenario'],f"{r['return_pct']:+.2f}",f"{r['max_drawdown_pct']:.2f}",f"{r['realized_vol_pct']:.2f}",r['round_trips'],f"{r['fees']+r['impact']:.2f}"] for r in rows],'all-accounts')+'</details></section>'
